pub fn _measure_half_width_height_548(
    mut node: Ptr<YGNode>,
    mut width: (),
    mut _a2: YGMeasureMode,
    mut height: (),
    mut _a4: YGMeasureMode,
) -> YGSize {
    let mut measureCount: Ptr<()> =
        ({ YGNodeGetContext_290((node).clone()) }).reinterpret_cast::<()>();
    if !((measureCount).is_null()) {
        measureCount.with_mut(|__v| __v.postfix_inc());
    }
    return YGSize {
        width: (0.5_f32 * width),
        height: (0.5_f32 * height),
    };
}
